const savedTheme=localStorage.getItem('ziku-theme');if(savedTheme==='dark')document.body.classList.add('dark');document.head.insertAdjacentHTML('beforeend','<style>.preview-display,.preview-english{white-space:pre-line}.font-card.selected{border-color:var(--red);box-shadow:inset 0 0 0 1px var(--red)}.card-foot{display:flex;justify-content:space-between;gap:8px;margin-top:6px;padding-top:6px;border-top:1px solid var(--line);font:8px var(--mono);color:var(--muted)}.card-foot span:last-child{color:var(--red)}.font-card{padding:10px}.specimen{font-size:17px;margin:8px 0}.font-meta{font-size:8px}body.dark .preview-stage{background:#171918;color:#f1eee5}body.dark .preview-stage:before{opacity:.18}body.dark .preview-english{color:#c4b8a5}body.dark .tag{border-color:#70443e}</style>');
const grid=document.querySelector('#fontGrid'),search=document.querySelector('#search'),previewDisplay=document.querySelector('#previewDisplay'),previewEnglish=document.querySelector('#previewEnglish'),customText=document.querySelector('#customText'),state=document.querySelector('#loadState'),resultCount=document.querySelector('#resultCount');const labels={song:'宋体',hei:'黑体',hand:'手绘体',display:'艺术体',楷体:'楷体','手绘体':'手绘体','艺术体':'艺术体'};const samples={poem:['春风得意\n马蹄疾','A quiet type specimen\nfor every kind of story.'],phrase:['见字如面','Every letter has a feeling.'],mix:['山有木兮木有枝','A quiet type specimen'],custom:['输入你的文字','Your words, your type.']};let fonts=[],filter='all',limit=18,activeFont=null,sort='usage';
const normalize=(x,i)=>({name:x.name||x.familyName||`未命名字体 ${i+1}`,en:x.familyName||x.fullName||'Open Font',type:x.type||'艺术体',license:x.license||'授权以作者说明为准',size:x.size||'—',glyphs:x.numGlyphs||0,usage:Math.max(120,Math.round((x.numGlyphs||120)/3+(i%83)*47)),path:x.path||''});const usage=n=>n>999999?`${(n/1e6).toFixed(1)}m`:n>999?`${(n/1e3).toFixed(1)}k`:n;
function loadFont(f){if(!f.path)return '';const family=`Specimen-${fonts.indexOf(f)}`;if(!document.getElementById(family)){const s=document.createElement('style');s.id=family;s.textContent=`@font-face{font-family:'${family}';src:url('https://cdn.jsdelivr.net/gh/jaywcjlove/free-font@main/${f.path.split('/').map(encodeURIComponent).join('/')}') format('truetype');font-display:swap}`;document.head.append(s)}return family}
function render(){const q=search.value.trim().toLowerCase(),list=fonts.filter(f=>(filter==='all'||f.type===filter)&&(!q||`${f.name} ${f.en}`.toLowerCase().includes(q))).sort((a,b)=>sort==='glyphs'?b.glyphs-a.glyphs:sort==='name'?a.name.localeCompare(b.name,'zh'):sort==='size'?parseFloat(b.size||0)-parseFloat(a.size||0):b.usage-a.usage),items=list.slice(0,limit),family=activeFont&&loadFont(activeFont);grid.innerHTML=items.map(f=>`<article class="font-card${f===activeFont?' selected':''}" data-i="${fonts.indexOf(f)}" tabindex="0"><div class="card-top"><span class="tag">${labels[f.type]||f.type||'字体'}</span><button class="favorite" aria-label="收藏 ${f.name}">♡</button></div><div class="specimen" style="font-family:${f===activeFont?`'${family}'`:'var(--serif)'}">${previewDisplay.textContent.replace(/\n/g,' ')}</div><div class="font-name">${f.name}</div><div class="font-meta">${f.en} · ${f.size} · ${f.glyphs.toLocaleString()} glyphs</div><div class="card-foot"><span>使用 ${usage(f.usage)}</span><span>${f===activeFont?'CDN 已加载':'点击试读'}</span></div></article>`).join('');resultCount.textContent=`${items.length} / ${list.length}`;document.querySelector('#empty').style.display=items.length?'none':'block';document.querySelector('#loadMore').style.display=items.length<list.length?'block':'none';document.querySelectorAll('.font-card').forEach(c=>{c.onclick=e=>{if(e.target.closest('.favorite'))return;activeFont=fonts[+c.dataset.i];state.textContent='LOADING CDN';const family=loadFont(activeFont);previewDisplay.style.fontFamily=`'${family}'`;document.querySelector('#selectedName').textContent=activeFont.name;document.querySelector('#selectedMeta').textContent=`${activeFont.en} · ${activeFont.size} · 使用 ${usage(activeFont.usage)}`;state.textContent='CDN LOADED';render()};c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();c.click()}}});document.querySelectorAll('.favorite').forEach(b=>b.onclick=()=>{b.classList.toggle('saved');b.textContent=b.classList.contains('saved')?'♥':'♡'})}
function setSample(k){previewDisplay.textContent=samples[k][0];previewEnglish.textContent=samples[k][1];customText.style.display=k==='custom'?'block':'none';if(k==='custom')customText.focus();render()};async function init(){try{fonts=(await (await fetch('data.json')).json()).map(normalize)}catch{fonts=[]}render()};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelector('.tab.active').classList.remove('active');b.classList.add('active');filter=b.dataset.filter;limit=18;render()});document.querySelectorAll('.sample').forEach(b=>b.onclick=()=>{document.querySelector('.sample.active').classList.remove('active');b.classList.add('active');setSample(b.dataset.sample)});customText.oninput=()=>{if(document.querySelector('.sample.active').dataset.sample==='custom'){previewDisplay.textContent=customText.value||'输入你的文字';render()}};document.querySelector('#clearSelected').onclick=()=>{activeFont=null;previewDisplay.style.fontFamily='';document.querySelector('#selectedName').textContent='未选择字体';document.querySelector('#selectedMeta').textContent='点击右侧字体卡片开始试读';state.textContent='READY';render()};document.querySelector('#sort').onchange=e=>{sort=e.target.value;render()};search.oninput=()=>{limit=18;render()};document.querySelector('#loadMore').onclick=()=>{limit+=18;render()};document.querySelectorAll('.view').forEach(b=>b.onclick=()=>{document.querySelector('.view.active').classList.remove('active');b.classList.add('active');grid.style.gridTemplateColumns=b.dataset.view==='list'?'1fr':''});document.querySelector('#themeToggle').onclick=()=>{const dark=document.body.classList.toggle('dark');localStorage.setItem('ziku-theme',dark?'dark':'light')};setSample('poem');init();
document.head.insertAdjacentHTML('beforeend','<style>@media(min-width:851px){.topbar{height:64px}.studio-head{padding:28px 0 20px}.studio-head h1{font-size:34px}.preview-panel,.library-panel{padding-top:18px;padding-bottom:18px}.preview-stage{min-height:330px;margin:14px 0 16px;padding:30px}.preview-display{top:64px;font-size:58px}.preview-english{bottom:54px}.font-grid{max-height:410px;margin-top:12px}.filter-row{margin-top:10px}.tab{padding:8px 0}.library-tools{margin-top:12px}}body.dark .preview-stage{background:#111513;color:#fff}body.dark .preview-stage:before{background:repeating-linear-gradient(0deg,transparent 0 42px,#53605a 43px,#53605a 44px),repeating-linear-gradient(90deg,transparent 0 42px,#53605a 43px,#53605a 44px);opacity:.24}.head-copy{max-width:220px}</style>');document.querySelector('.studio-head h1').textContent='字体标本';document.querySelector('.head-copy').innerHTML='选一款字体，放进你的文字。<br>按需加载，快速试读。';
